-- Creative sample transactions for this calendar month and the three previous months.
-- Each month has 30 DEBIT expenses and 5 CREDIT incomes, with unique descriptions by month.
-- Running this script deletes all existing expenses, then inserts 140 sample rows.

DELETE FROM expenses;

INSERT INTO expenses (date, category, description, amount, type)
SELECT DATEADD('DAY', LEAST(sample.day_of_month - 1,
                           DAY(LAST_DAY(DATEADD('MONTH', sample.month_offset,
                                               DATE_TRUNC('MONTH', CURRENT_DATE)))) - 1),
               DATEADD('MONTH', sample.month_offset,
                       DATE_TRUNC('MONTH', CURRENT_DATE))),
       sample.category,
       sample.description,
       sample.amount,
       sample.type
